// The Gleam compiler denext pins: one exact gleam-lang/gleam release, a SHA-256 per host target in
// `gleam-toolchain-pin.json` (regenerated by `deno task gleam:pin <version>`), fetched on first need
// into the toolchain cache beside the managed Deno (`<DENO_DIR>/denext-deno/gleam/<version>/
// <target>/gleam[.exe]`) through the same verified, locked, atomic install as the Deno toolchain
// (`ensureCached` in deno-toolchain.ts): streamed to a temp file, refused on a size or SHA-256
// mismatch before anything is extracted, extracted, renamed into place, stamped last.
//
// "First need" is `denext add gleam:<package>`, the `gleam()` plugin at dev / build, or the prefetch
// `denext toolchain install --with gleam`. Gleam's JavaScript target needs no Erlang, so this one
// binary is the whole of it. Linux takes the static musl builds, which run on any distribution.
//
// Resolution: an explicit `gleam` option, then `DENEXT_GLEAM=<path>` (that binary, unverified),
// then the pinned copy. A `gleam` on PATH is never picked up implicitly: its version would decide
// what the app's JavaScript looks like, so it is used only when named (`DENEXT_GLEAM`, or the
// plugin's `gleam` option).

import { join, resolve } from "@std/path";
import {
  cachedSlotState,
  type CacheSlot,
  type DenoToolchainArtifact,
  denoToolchainCacheRoot,
  denoToolchainTarget,
  DenoToolchainUnavailableError,
  ensureCached,
  type EnsureDenoToolchainOptions,
  toolchainEnvValue,
} from "./deno-toolchain.ts";
import pinJson from "./gleam-toolchain-pin.json" with { type: "json" };

/** The pin's host targets (`Deno.build`'s `<os>-<arch>`) → the release asset's target triple. */
export const GLEAM_TARGET_TRIPLES: Readonly<Record<string, string>> = {
  "darwin-aarch64": "aarch64-apple-darwin",
  "darwin-x86_64": "x86_64-apple-darwin",
  "linux-aarch64": "aarch64-unknown-linux-musl",
  "linux-x86_64": "x86_64-unknown-linux-musl",
  "windows-aarch64": "aarch64-pc-windows-msvc",
  "windows-x86_64": "x86_64-pc-windows-msvc",
};

/** The pinned Gleam release (`gleam-toolchain-pin.json`). */
export interface GleamToolchainPin {
  readonly schema: 1;
  /** The Gleam version (`1.18.1`). */
  readonly version: string;
  /** The release tag (`v1.18.1`). */
  readonly tag?: string;
  readonly repository?: string;
  /** When the release was published (pins are at least two weeks old). */
  readonly published?: string;
  /** Per host target (`darwin-aarch64`, `linux-x86_64`, `windows-x86_64`, …). */
  readonly targets: Readonly<Record<string, DenoToolchainArtifact>>;
}

/** The Gleam denext pins. */
export const GLEAM_TOOLCHAIN: GleamToolchainPin = pinJson as GleamToolchainPin;

/** `DENEXT_GLEAM=<path>`: run that `gleam` (unverified) instead of the pinned one. */
export const GLEAM_ENV = "DENEXT_GLEAM";

/** The command that fetches the pinned Gleam ahead of time (for offline work). */
export const GLEAM_PREFETCH = "denext toolchain install --with gleam";

/** Env reader. */
type EnvGet = (k: string) => string | undefined;
const processEnv: EnvGet = (k) => {
  try {
    return Deno.env.get(k);
  } catch {
    return undefined;
  }
};

/** Options for {@linkcode ensureGleamToolchain} and {@linkcode resolveGleamToolchain}. */
export interface GleamToolchainOptions extends Omit<EnsureDenoToolchainOptions, "pin"> {
  /** Defaults to {@linkcode GLEAM_TOOLCHAIN}. */
  readonly pin?: GleamToolchainPin;
  /** Env reader (default `Deno.env.get`). */
  readonly env?: EnvGet;
}

/** A verified pinned `gleam`. */
export interface ResolvedGleam {
  /** The executable to run. */
  readonly gleam: string;
  /** The pinned version, or `path` for a `DENEXT_GLEAM` binary. */
  readonly version: string;
  /** Whether nothing was downloaded. */
  readonly cached: boolean;
  /** Say this once (the unverified `DENEXT_GLEAM=<path>` override). */
  readonly warning?: string;
}

/** The cache slot of the pinned `gleam` for this host, or why there is none. */
function gleamSlot(options: GleamToolchainOptions): CacheSlot {
  const pin = options.pin ?? GLEAM_TOOLCHAIN;
  const target = options.target ?? denoToolchainTarget();
  const artifact = pin.targets[target];
  if (!artifact) {
    throw new DenoToolchainUnavailableError(
      `denext: the pinned Gleam ${pin.version} has no build for ${target} (it has: ` +
        `${Object.keys(pin.targets).join(", ") || "none"}). Set ${GLEAM_ENV}=<path> to a gleam ` +
        `${pin.version} built for this machine.`,
    );
  }
  const root = options.cacheRoot ?? denoToolchainCacheRoot(options.env ?? processEnv);
  const os = options.os ?? target.split("-")[0];
  return {
    root,
    dir: join(root, "gleam", pin.version, target),
    exe: os === "windows" ? "gleam.exe" : "gleam",
    os,
    version: pin.version,
    target,
    artifact,
    what: "Gleam compiler",
    offlineHint: `Run \`${GLEAM_PREFETCH}\` once while online, or set ${GLEAM_ENV}=<path> to a ` +
      `gleam ${pin.version}.`,
  };
}

/**
 * Make the pinned `gleam` for this host available in the toolchain cache — SHA-256-verified,
 * installed atomically under the cache lock — and return it. Throws the toolchain's errors:
 * `DenoToolchainUnavailableError` (no build for this host), `DenoToolchainDownloadError` (offline,
 * HTTP, truncated; the message names {@linkcode GLEAM_PREFETCH}) and `DenoToolchainHashError`.
 *
 * @param options Seams; all default to the process.
 * @returns The binary.
 */
export async function ensureGleamToolchain(
  options: GleamToolchainOptions = {},
): Promise<ResolvedGleam> {
  const slot = gleamSlot(options);
  const cached = await ensureCached(slot, options);
  return { gleam: join(slot.dir, slot.exe), version: slot.version, cached };
}

/**
 * The `gleam` denext runs: `DENEXT_GLEAM=<path>` when set (it must be a file), else the pinned
 * copy, downloaded and verified on first need ({@linkcode ensureGleamToolchain}).
 *
 * @param options Seams; all default to the process.
 * @returns The binary to run.
 */
export async function resolveGleamToolchain(
  options: GleamToolchainOptions = {},
): Promise<ResolvedGleam> {
  const raw = toolchainEnvValue(options.env ?? processEnv, GLEAM_ENV);
  if (raw === "") return await ensureGleamToolchain(options);
  const path = resolve(raw);
  if (!(await Deno.stat(path).catch(() => null))?.isFile) {
    throw new DenoToolchainUnavailableError(`denext: ${GLEAM_ENV}=${path} is not a file.`);
  }
  return {
    gleam: path,
    version: "path",
    cached: true,
    warning: `denext: using the gleam at ${path} (${GLEAM_ENV}); it is not downloaded, pinned ` +
      "or verified.",
  };
}

/** The pinned Gleam on this machine (`denext toolchain status`). */
export interface GleamToolchainStatus {
  /** `pinned`, or `path` under `DENEXT_GLEAM`. */
  readonly mode: "pinned" | "path";
  readonly version: string;
  readonly target: string;
  /** `cached` = present + verified; `missing` = downloads on first need; `invalid` = re-downloads. */
  readonly state: "cached" | "missing" | "invalid" | "unsupported" | "n/a";
  /** The binary (`null` when there is none for this host). */
  readonly path: string | null;
  /** Whether nothing needs fixing (a missing cache is fine: it downloads on first need). */
  readonly ok: boolean;
  /** One line for a report. */
  readonly detail: string;
}

const STATE_TEXT: Record<GleamToolchainStatus["state"], string> = {
  cached: "cached + verified",
  missing: `not cached yet (downloaded on first need, or now with \`${GLEAM_PREFETCH}\`)`,
  invalid: "cache FAILED verification (re-downloaded on next use)",
  unsupported: `no build for this host (set ${GLEAM_ENV}=<path>)`,
  "n/a": "",
};

/**
 * Report the pinned Gleam: its version, and whether it is cached and verified. Never downloads.
 *
 * @param options Seams, plus `verify` to re-hash a cached binary.
 * @returns The status.
 */
export async function gleamToolchainStatus(
  options: GleamToolchainOptions & { readonly verify?: boolean } = {},
): Promise<GleamToolchainStatus> {
  const pin = options.pin ?? GLEAM_TOOLCHAIN;
  const target = options.target ?? denoToolchainTarget();
  const raw = toolchainEnvValue(options.env ?? processEnv, GLEAM_ENV);
  const base = { version: pin.version, target };
  if (raw !== "") {
    const path = resolve(raw);
    const exists = (await Deno.stat(path).catch(() => null))?.isFile === true;
    return {
      ...base,
      mode: "path",
      state: "n/a",
      path,
      ok: exists,
      detail: `${GLEAM_ENV}=${path} (unverified)${exists ? "" : " — NOT FOUND"}`,
    };
  }
  if (!pin.targets[target]) {
    return {
      ...base,
      mode: "pinned",
      state: "unsupported",
      path: null,
      ok: true,
      detail: `gleam ${pin.version} for ${target}; ${STATE_TEXT.unsupported}`,
    };
  }
  const slot = gleamSlot({ ...options, pin, target });
  const state = await cachedSlotState(slot, options.verify === true);
  return {
    ...base,
    mode: "pinned",
    state,
    path: join(slot.dir, slot.exe),
    ok: state !== "invalid",
    detail: `gleam ${pin.version} for ${target}; ${STATE_TEXT[state]}`,
  };
}
